INSERT INTO `#__methodology_topics` (`slug`, `kind`, `status`, `title`, `tagline`, `short_description`, `description`, `author_slug`, `reviewer_slug`, `version`, `last_updated`, `tmpl`, `schema_type`, `external_url`, `sort_order`) VALUES ('fxclock', 'methodology', 'live', 'How FXClock Works: Payouts Timed by Players', 'Two taps, one fact. Players time their own withdrawals from request to receipt; the clocks run in public, the median shows only from ten, and nobody at the desk can edit one.', 'FXClock replaces star ratings with a stopwatch: one tap when a withdrawal is requested, one when the money lands. Four verification grades, a public median from ten clocks, refused and unresolved counted separately, and an append-only record the desk cannot touch.', 'Methodology behind FXClock on FreeExtraChips casino reviews: how player-timed withdrawal clocks work, the four verification grades (on-chain, deposit, contact, anonymous), the ten-clock threshold, abuse controls, retention, and why the data never merges with the FXShield Safety Index.', 'mark-sullivan', 'david-romano', 'v1.0', '2026-09-22', 'fxclock', NULL, NULL, 36) ON DUPLICATE KEY UPDATE `kind` = VALUES(`kind`), `status` = VALUES(`status`), `title` = VALUES(`title`), `tagline` = VALUES(`tagline`), `short_description` = VALUES(`short_description`), `description` = VALUES(`description`), `author_slug` = VALUES(`author_slug`), `reviewer_slug` = VALUES(`reviewer_slug`), `tmpl` = VALUES(`tmpl`), `version` = VALUES(`version`), `last_updated` = VALUES(`last_updated`), `sort_order` = VALUES(`sort_order`);
